def find_triplets_sum_zero(arr):
    # O(N^3) brute force approach with duplicate checking
    result = []
    n = len(arr)
    seen = set()

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if arr[i] + arr[j] + arr[k] == 0:
                    triplet = tuple(sorted([arr[i], arr[j], arr[k]]))
                    if triplet not in seen:
                        seen.add(triplet)
                        result.append(list(triplet))

    return result

def longest_common_subsequence(s1, s2):
    # O(2^min(m,n)) recursive approach without memoization
    def lcs_recursive(i, j):
        if i == len(s1) or j == len(s2):
            return 0

        if s1[i] == s2[j]:
            return 1 + lcs_recursive(i + 1, j + 1)
        else:
            return max(lcs_recursive(i + 1, j), lcs_recursive(i, j + 1))

    return lcs_recursive(0, 0)

def count_subarrays_with_sum(arr, target_sum):
    # O(N^2) brute force - check all subarrays
    count = 0
    n = len(arr)

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += arr[j]
            if current_sum == target_sum:
                count += 1

    return count

def find_duplicate_pairs(nums):
    # O(N^2) brute force comparison
    result = []
    n = len(nums)

    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] == nums[j]:
                result.append([i, j])

    return result

def matrix_max_path_sum(matrix):
    # O(2^(m+n)) recursive approach without memoization
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])

    def max_path(i, j):
        if i == m - 1 and j == n - 1:
            return matrix[i][j]

        if i == m - 1:
            return matrix[i][j] + max_path(i, j + 1)

        if j == n - 1:
            return matrix[i][j] + max_path(i + 1, j)

        return matrix[i][j] + max(max_path(i + 1, j), max_path(i, j + 1))

    return max_path(0, 0)
